const data = msg.payload;

// Validar que el payload sea un objeto
if (typeof data !== "object" || data === null || Array.isArray(data)) {
    msg.payload = {
        valido: false,
        error: "El payload recibido no es un objeto JSON válido",
        recibido: data
    };

    return [null, msg];
}

// Campos obligatorios
const camposObligatorios = [
    "dispositivo",
    "aula",
    "temperatura",
    "humedad",
    "umbral",
    "alerta",
    "estado",
    "uptime"
];

const camposFaltantes = camposObligatorios.filter(
    campo => data[campo] === undefined || data[campo] === null
);

if (camposFaltantes.length > 0) {
    msg.payload = {
        valido: false,
        error: "Faltan campos obligatorios",
        camposFaltantes,
        recibido: data
    };

    return [null, msg];
}

// Validar tipos de datos
const errores = [];

if (typeof data.dispositivo !== "string" || data.dispositivo.trim() === "") {
    errores.push("dispositivo debe ser un texto no vacío");
}

if (typeof data.aula !== "string" || data.aula.trim() === "") {
    errores.push("aula debe ser un texto no vacío");
}

if (typeof data.temperatura !== "number" || !Number.isFinite(data.temperatura)) {
    errores.push("temperatura debe ser un número válido");
}

if (typeof data.humedad !== "number" || !Number.isFinite(data.humedad)) {
    errores.push("humedad debe ser un número válido");
}

if (typeof data.umbral !== "number" || !Number.isFinite(data.umbral)) {
    errores.push("umbral debe ser un número válido");
}

if (typeof data.alerta !== "boolean") {
    errores.push("alerta debe ser true o false");
}

if (typeof data.estado !== "string" || data.estado.trim() === "") {
    errores.push("estado debe ser un texto no vacío");
}

if (typeof data.uptime !== "number" || !Number.isFinite(data.uptime)) {
    errores.push("uptime debe ser un número válido");
}

// Validar rangos razonables
if (
    typeof data.temperatura === "number" &&
    (data.temperatura < -40 || data.temperatura > 80)
) {
    errores.push("temperatura fuera del rango permitido");
}

if (
    typeof data.humedad === "number" &&
    (data.humedad < 0 || data.humedad > 100)
) {
    errores.push("humedad fuera del rango permitido");
}

if (errores.length > 0) {
    msg.payload = {
        valido: false,
        error: "La telemetría contiene datos inválidos",
        detalles: errores,
        recibido: data
    };

    return [null, msg];
}

// Normalizar datos válidos
msg.payload = {
    dispositivo: data.dispositivo.trim(),
    aula: data.aula.trim(),
    temperatura: Number(data.temperatura.toFixed(2)),
    humedad: Number(data.humedad.toFixed(2)),
    umbral: Number(data.umbral.toFixed(2)),
    alerta: data.alerta,
    estado: data.estado.trim().toUpperCase(),
    uptime: data.uptime,
    recibido_en: new Date().toISOString()
};

msg.headers = {
    "Content-Type": "application/json"
};

return [msg, null];
